#Requires -Version 5.1
# feat-rrhh-disponibilidad.ps1
# Centraliza la logica de disponibilidad de RRHH:
#
# ARCHIVO NUEVO: src/lib/utils/disponibilidadRrhh.ts
#   - checkRrhhDisponibilidad(rrhh, fecha): valida activo + asignable + fecha_inicio + fecha_fin
#   - filtrarRrhhDisponibles(recursos, fecha): filtra array
#   - formatFechaES(fecha): YYYY-MM-DD -> DD/MM/YYYY para mensajes de usuario
#
# TIPOS: src/lib/types/database.ts
#   - RecursoHumano: añadidos campos asignable, fecha_inicio, fecha_fin
#
# PLANIFICADOR: src/app/planificacion/page.tsx
#   1. Panel lateral: recursos filtrados por fecha del dia visible
#   2. Modal manual: recursos filtrados por fecha_inicio del rango
#   3. Drag Vista Obras: valida antes de insertar en Supabase
#   4. Drag Vista RRHH: valida antes de insertar en Supabase
#   5. handleManualAssign: valida cada dia del rango, muestra mensaje si bloqueado
#   6. Panel movil "sin asignar": filtrado por disponibilidad en el dia movil
#
# API SERVER-SIDE: src/app/api/asignaciones/validar/route.ts (NUEVO)
#   - POST con recurso_tipo, recurso_id, fecha_inicio, fecha_fin, obra_id
#   - Valida consultando la BD directamente (no se puede bypassear desde cliente)
#   - Devuelve { valido: true } o { valido: false, motivo: "mensaje" }

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> feat: disponibilidad RRHH centralizada" -ForegroundColor Cyan

Write-Host "  -> src\lib\utils\disponibilidadRrhh.ts" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\lib\utils\disponibilidadRrhh.ts")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\lib\utils\disponibilidadRrhh.ts"), $bytes)
Write-Host "  OK: 2 KB" -ForegroundColor Green

Write-Host "  -> src\lib\types\database.ts" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\lib\types\database.ts")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\lib\types\database.ts"), $bytes)
Write-Host "  OK: 11 KB" -ForegroundColor Green

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\planificacion\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 71 KB" -ForegroundColor Green

Write-Host "  -> src\app\api\asignaciones\validar\route.ts" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\api\asignaciones\validar\route.ts")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\api\asignaciones\validar\route.ts"), $bytes)
Write-Host "  OK: 1 KB" -ForegroundColor Green

$ok1 = Test-Path (Join-Path $RepoPath "src\lib\utils\disponibilidadRrhh.ts")
$ok2 = (Get-Content (Join-Path $RepoPath "src\lib\types\database.ts") -Raw).Contains("fecha_inicio: string | null")
$ok3 = (Get-Content (Join-Path $RepoPath "src\app\planificacion\page.tsx") -Raw).Contains("checkRrhhDisponibilidad")
$ok4 = Test-Path (Join-Path $RepoPath "src\app\api\asignaciones\validar\route.ts")
if ($ok1) { Write-Host "  OK: disponibilidadRrhh.ts creado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($ok2) { Write-Host "  OK: tipos RecursoHumano actualizados" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($ok3) { Write-Host "  OK: planificador usa checkRrhhDisponibilidad" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($ok4) { Write-Host "  OK: API route validar creada" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "feat: disponibilidad RRHH - funcion centralizada + validacion server-side"'
Write-Host "  git push"
